import json
import re
from docx import Document
from docx.enum.text import WD_COLOR_INDEX

with open('/home/user/Desktop/llm_answers.json') as f:
    data = json.load(f)

def find_gemini(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if k.lower() == 'gemini':
                results.append((new_path, v))
            else:
                results.extend(find_gemini(v, new_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_gemini(item, f'{path}[{i}]'))
    return results

found = find_gemini(data)
responses = [val for _, val in found if isinstance(val, str)]

doc = Document()

pattern = re.compile(r'(Iliad)', re.IGNORECASE)

for idx, resp in enumerate(found):
    path, val = resp
    if not isinstance(val, str):
        continue
    # Each response should be a new paragraph; preserve internal newlines as separate paragraphs
    # Split into lines/paragraphs by newline
    lines = val.split('\n')
    for line in lines:
        p = doc.add_paragraph()
        if not line.strip():
            continue
        # Split line by 'Iliad' (case-insensitive) keeping the matches
        parts = pattern.split(line)
        for part in parts:
            if part == '':
                continue
            run = p.add_run(part)
            if pattern.fullmatch(part):
                run.font.highlight_color = WD_COLOR_INDEX.YELLOW
    # Add an empty paragraph between responses (new line separator)
    if idx < len(found) - 1:
        doc.add_paragraph()

doc.save('/home/user/Desktop/gemini_results.docx')
print('Saved. Responses:', len(responses))

